class Solution {
public:
    long long minCost(vector<int>& nums, vector<int>& cost) {
        int n = nums.size();
        vector<pair<int, int>> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = {nums[i], cost[i]};
        }
        sort(arr.begin(), arr.end());

        vector<long long> prefixCost(n + 1, 0);
        vector<long long> prefixWeighted(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefixCost[i + 1] = prefixCost[i] + arr[i].second;
            prefixWeighted[i + 1] = prefixWeighted[i] + (long long)arr[i].first * arr[i].second;
        }

        long long ans = (long long)1e18;
        for (int k = 0; k < n; k++) {
            long long target = arr[k].first;
            long long leftCost = target * prefixCost[k] - prefixWeighted[k];
            long long rightCost = (prefixWeighted[n] - prefixWeighted[k + 1]) 
                                - target * (prefixCost[n] - prefixCost[k + 1]);
            ans = min(ans, leftCost + rightCost);
        }

        return ans;
    }
};
